import pandas as pd, numpy as np, re

df=pd.read_csv('benchmark/data.csv')

def parse_money(s):
    if pd.isna(s): return np.nan
    s=str(s).replace('₹','').replace(',','').strip()
    try:
        return float(s)
    except:
        return np.nan

def parse_pct(s):
    if pd.isna(s): return np.nan
    s=str(s).strip().replace('%','')
    try:
        return float(s)
    except:
        return np.nan

def parse_int(s):
    if pd.isna(s): return np.nan
    s=str(s).replace(',','').strip()
    try:
        return int(float(s))
    except:
        return np.nan

def parse_rating(x):
    if pd.isna(x): return np.nan
    s=str(x).strip()
    m=re.search(r"\d+(?:\.\d+)?", s)
    return float(m.group(0)) if m else np.nan

cdf=df.copy()
for col,fn in [('discounted_price_num',parse_money),('actual_price_num',parse_money)]:
    cdf[col]=cdf[col.replace('_num','')].map(fn)
cdf['discount_pct_num']=cdf['discount_percentage'].map(parse_pct)
cdf['rating_num']=cdf['rating'].map(parse_rating)
cdf['rating_count_num']=cdf['rating_count'].map(parse_int)
parts=cdf['category'].astype(str).str.split('|')
cdf['category_l1']=parts.str[0]
cdf['category_l2']=parts.str[1]

agg=cdf.groupby('category_l1').agg(products=('product_id','count'),avg_rating=('rating_num','mean'),avg_disc=('discount_pct_num','mean'),median_rating_count=('rating_count_num','median'))
print(agg.sort_values('products',ascending=False))
