import pandas as pd, numpy as np, re

df=pd.read_csv('benchmark/data.csv')

def parse_money(s):
    if pd.isna(s): return np.nan
    s=str(s).replace('₹','').replace(',','').strip()
    try:
        return float(s)
    except:
        return np.nan

def parse_pct(s):
    if pd.isna(s): return np.nan
    s=str(s).strip().replace('%','')
    try:
        return float(s)
    except:
        return np.nan

def parse_int(s):
    if pd.isna(s): return np.nan
    s=str(s).replace(',','').strip()
    try:
        return int(float(s))
    except:
        return np.nan

def parse_rating(x):
    if pd.isna(x): return np.nan
    s=str(x).strip()
    m=re.search(r"\d+(?:\.\d+)?", s)
    return float(m.group(0)) if m else np.nan

cdf=df.copy()
cdf['discounted_price_num']=cdf['discounted_price'].map(parse_money)
cdf['actual_price_num']=cdf['actual_price'].map(parse_money)
cdf['discount_pct_num']=cdf['discount_percentage'].map(parse_pct)
cdf['rating_num']=cdf['rating'].map(parse_rating)
cdf['rating_count_num']=cdf['rating_count'].map(parse_int)
parts=cdf['category'].astype(str).str.split('|')
cdf['category_l1']=parts.str[0]

# bins
bins=[0,250,500,1000,2000,5000,1e9]
labels=['<₹250','₹250-499','₹500-999','₹1k-1,999','₹2k-4,999','₹5k+']
cdf['price_band']=pd.cut(cdf['discounted_price_num'], bins=bins, labels=labels, right=False)

band=cdf.groupby('price_band', observed=True).agg(products=('product_id','count'),avg_rating=('rating_num','mean'),avg_disc=('discount_pct_num','mean'),median_rating_count=('rating_count_num','median'))
print(band)

# correlation in each band between discount and rating
for b in labels:
    sub=cdf[cdf['price_band']==b][['discount_pct_num','rating_num','rating_count_num']].dropna()
    if len(sub)>=30:
        print(b, 'n', len(sub), 'corr(disc,rating)', sub[['discount_pct_num','rating_num']].corr().iloc[0,1], 'corr(disc,count)', sub[['discount_pct_num','rating_count_num']].corr().iloc[0,1])
